// Diagnostic (ticket 57), not in unit_test.dart. Opens every clip in
// VARIANTS_DIR (plus the committed fixtures) through the real video binding at
// 128x72, decodes the whole clip and reports outcome + first-frame pixels.
// Variants are generated by the shell loop in the ticket report (ffmpeg).
//
//   VARIANTS_DIR=/path flutter test test_diagnostic/clip_variants_test.dart
import 'dart:ffi';
import 'dart:io';

import 'package:ffi/ffi.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:video_native/video_native.dart';

void main() {
  final binding = NativeVideoBinding.probe();
  test('every clip opens, decodes and is not blank', () {
    expect(binding.isAvailable, isTrue, reason: '${binding.availability}');
    final files = <File>[
      ...Directory('native/probe/fixtures').listSync().whereType<File>(),
      if (Platform.environment['VARIANTS_DIR'] case final d?)
        ...Directory(d).listSync().whereType<File>(),
    ]..sort((a, b) => a.path.compareTo(b.path));
    const w = 128, h = 72;
    final bad = <String>[];
    for (final f in files) {
      final name = f.path.split('/').last;
      final r = binding.open(f.readAsBytesSync(), width: w, height: h);
      if (r is! VideoOpened) {
        bad.add('$name OPEN ${(r as VideoRejected).reason}');
        continue;
      }
      final target = calloc<Uint8>(w * h * 4);
      try {
        var frames = 0;
        var firstVisible = -1;
        var status = VideoFrameStatus.frame;
        while (true) {
          final res = binding.nextFrame(
            r.handle,
            target: target,
            strideBytes: w * 4,
          );
          status = res.status;
          if (status != VideoFrameStatus.frame) break;
          if (frames == 0) {
            final px = target.asTypedList(w * h * 4);
            var visible = 0;
            for (var i = 0; i < px.length; i += 4) {
              if (px[i + 3] != 0 && (px[i] | px[i + 1] | px[i + 2]) != 0) {
                visible++;
              }
            }
            firstVisible = visible;
          }
          frames++;
        }
        // ignore: avoid_print
        print(
          '$name src=${r.info.width}x${r.info.height} frames=$frames '
          'end=$status firstFrameVisiblePx=$firstVisible/${w * h}',
        );
        if (frames == 0 ||
            firstVisible == 0 ||
            status != VideoFrameStatus.endOfStream) {
          bad.add('$name frames=$frames visible=$firstVisible end=$status');
        }
      } finally {
        calloc.free(target);
        binding.dispose(r.handle);
      }
    }
    expect(bad, isEmpty);
  });
}
